// Class names generated by CSS-in-JS / CSS modules change whenever a site is
// rebuilt. Entry and account locators must anchor on ids, data attributes,
// stable text or structure instead. Configs captured on or after the rule date
// are refused; older ones are reported by the readiness check for recapture.
export const STABLE_SELECTOR_RULE_SINCE='2026-10-26';
const hashLike=s=>/[0-9]/.test(s)||/[a-z][A-Z]|[A-Z][a-z][A-Z]/.test(s);
export function unstableClassTokens(selector){
 if(typeof selector!=='string')return [];
 const tokens=[...selector.matchAll(/\.(-?[_a-zA-Z][\w-]*)/g)].map(m=>m[1]);
 for(const m of selector.matchAll(/\[class[*^$|~]?=["']([^"']+)["']\]/g))tokens.push(...m[1].split(/\s+/));
 return [...new Set(tokens.filter(t=>{
  const sc=t.match(/(?:^|__)sc-([A-Za-z0-9]{5,10})(?:-\d+)?$/);if(sc&&hashLike(sc[1]))return true;
  if(/___[A-Za-z0-9_-]{5}$/.test(t))return true;
  const css=t.match(/^css-([a-z0-9]{5,})(?:-|$)/);if(css&&/[0-9]/.test(css[1]))return true;
  return false;
 }))];
}
const captured=evidence=>String(evidence?.capturedAt||'').slice(0,10);
export const ruleApplies=evidence=>captured(evidence)>=STABLE_SELECTOR_RULE_SINCE;
export function entrySelectors(entry){
 if(!entry)return [];
 return [['detail.roleSelector',entry.detail?.roleSelector],['detail.readySelector',entry.detail?.readySelector],['form.roleSelector',entry.form?.roleSelector],['form.readySelector',entry.form?.readySelector],['entryLocator.selector',entry.entryLocator?.selector],...(entry.preActions||[]).map((a,i)=>[`preActions[${i}].selector`,a?.selector])].filter(([,s])=>typeof s==='string');
}
export function unstableLocators(config){
 const out=[];
 for(const [where,s] of [...entrySelectors(config?.entry).map(([w,s])=>['entry.'+w,s]),['account.selector',config?.account?.selector]])for(const token of unstableClassTokens(s))out.push({where,token});
 return out;
}
